def diff_snapshot(a, b):
    ditambah = sorted(n for n in b if n not in a)
    dihapus = sorted(n for n in a if n not in b)
    diubah = sorted(n for n in a if n in b and a[n] != b[n])
    return (ditambah, dihapus, diubah)

